@app.route("/predict", methods=["POST"])
def predict():
data = request.get_json(force=True)
features = data.get("features", [])
if not features:
return jsonify({"error": "No features provided"}), 400
pred = model.predict([features])[0]
proba = max(model.predict_proba([features])[0])
result = {"class": int(pred), "probability": float(proba)}
# Запись в БД
conn = get_db()
cur = conn.cursor()
cur.execute(
"INSERT INTO predictions (input_data, prediction, model_version) VALUES
(%s, %s, %s)",
(json.dumps({"features": features}), json.dumps(result), "v1.0")
)
conn.commit()
cur.close()
conn.close()
return jsonify(result)

